"""Writes tests/HBHT.Rom.Tests/CasterExtraVectors.cs from the one-off vectors of extras.py (single, spellValueByKind, aiCanCast, danger,
moraleSpells), which CasterCheckpointTests checks the port against."""
from emit import entries, mods

TEMPLATE = '''namespace HBHT.Rom.Tests;

// Generated by tools/aivectors (python tools/aivectors/aivectors.py), do not edit: 1.0's own ScoreSpellCells by action slot,
// EnemyAI.SpellValue by spell kind, Combatant.AICanCast, the party's area danger (Combat.PartyPotionTier and CreatePartyCombatants) and
// the morale spells (Entity.AddEffect and AgeEffects for Aura of Death and Solar Wrath, and their removal), run in the MIPS interpreter
// on the combat checkpoints' RAM (extras.py). Entry lists are written "score,x,z,slot,combatant;" for each entry in order.
internal static class CasterExtraVectors
{
    /// <summary>ScoreSpellCells for one caster: all its action slots (Full), and each action slot alone (the others switched off).</summary>
    public sealed record Single(string Id, int Checkpoint, int Slot, int Entity, string Mods, int Radius, int[] ActionKinds, bool Independent,
        string Full, SingleSlot[] PerSlot)
    {
        public override string ToString() => Id;
    }

    /// <summary>The entries of one action slot scored alone, and the spell kind its AI byte held.</summary>
    public sealed record SingleSlot(int Index, int Kind, string Entries);

    /// <summary>SpellValue of a spell kind for the Sorceror at checkpoint 08, slot 5, with set B's candidates slots 0 to 5; Context is the changes made to the battle (the case mods' grammar).</summary>
    public sealed record KindValue(string Context, int Kind, int Value)
    {
        public override string ToString() => $"kind {Kind} [{Context}]";
    }

    /// <summary>AICanCast of a known spell or an item's at Alaron: the spell's kind, casting level and cost, the caster's modified Stamina, the item's charges (-1 none), and the answer.</summary>
    public sealed record AiCan(string Label, int Entity, int ActionSlot, int Kind, int Level, int Cost, int Stamina, int Charges, bool Result)
    {
        public override string ToString() => $"{Label} stamina {Stamina} charges {Charges}";
    }

    /// <summary>AICanCast of the Sorceror's spell at known index 3 with its struct's special byte (+0x1B) edited, by part of day; Requirement and TimeAllows are 1.0's own answers on the way.</summary>
    public sealed record AiCanSpecial(int Special, int PartOfDay, int Requirement, int TimeAllows, bool Result)
    {
        public override string ToString() => $"special {Special} part {PartOfDay}";
    }

    /// <summary>The area danger: the flasks the party holds (item ids), Fireballs learned (member, level), Wizard levels set (member, level), the dead, every member's Wizard level (modified), and the tier and the danger after the raise.</summary>
    public sealed record Danger(int[] Flasks, (int Member, int Level)[] Fireballs, (int Member, int Level)[] Wizard, int[] Dead, int[] MemberWizard, int Tier, int Value)
    {
        public override string ToString() => $"flasks [{string.Join(' ', Flasks.Select(f => f.ToString("X")))}] fireballs [{string.Join(' ', Fireballs)}] wizard [{string.Join(' ', Wizard)}] dead [{string.Join(' ', Dead)}]";
    }

    /// <summary>A morale spell (kind 25 Aura of Death or 47 Solar Wrath) cast on the rat at slot 5 with the morale it had, and the morale and the flags after, a second cast, and each round's ageing.</summary>
    public sealed record Morale(int Kind, int Morale0, int Power, int Timer, int MoraleAfterStart, int FlagsAfterStart, bool SecondRefused, int MoraleAfterSecond,
        (int Morale, bool Present)[] Rounds, int MoraleAtEnd)
    {
        public override string ToString() => $"kind {Kind} morale {Morale0} power {Power} timer {Timer}";
    }

    /// <summary>The morale spell taken off by a Dispel Necro (Path dispel), a lethal hit (lethal), Combatant.Death (death) or RemoveAllEffects (removeall).</summary>
    public sealed record Removal(string Path, int MoraleAfterStart, bool Dispelled, int MoraleAfter, bool RecordPresent)
    {
        public override string ToString() => Path;
    }

    public static readonly Single[] Singles =
    [
@SINGLES@
    ];

    public static readonly KindValue[] Kinds =
    [
@KINDS@
    ];

    public static readonly AiCan[] AiCans =
    [
@AICAN@
    ];

    public static readonly AiCanSpecial[] AiCanSpecials =
    [
@SPECIALS@
    ];

    public static readonly Danger[] Dangers =
    [
@DANGERS@
    ];

    public static readonly Morale[] Morales =
    [
@MORALES@
    ];

    public static readonly Removal[] Removals =
    [
@REMOVALS@
    ];
}
'''


def q(s):
    return '"' + s.replace('\\', '\\\\').replace('"', '\\"') + '"'


def ints(xs):
    return '[' + ', '.join(str(x) for x in xs) + ']'


def pairs(xs):
    return '[' + ', '.join(f'({a}, {b})' for a, b in xs) + ']'


def b(x):
    return 'true' if x else 'false'


# The effect kinds the dispel contexts lay (a helpful and a harmful effect of the dispel's school), as extras.kinds() lays them.
HELPFUL = {42: 3, 43: 13, 44: 32, 45: 48}
HARMFUL = {42: 5, 43: 14, 44: 31, 45: 52}


def kind_rows(k):
    """(context, kind, value): the case mods' grammar for the context (effect:slot,kind,power,timer,margin | entity:slot,id | daypart:part)."""
    rows = [('', int(kind), val) for kind, val in sorted(k['neutral'].items(), key=lambda kv: int(kv[0]))]
    for row in k['conditional']:
        kind, ctx = row['kind'], row['context']
        if kind == 2:
            rows.append(('effect:4,36,3,50,3', 2, row['value']))
        elif kind in (4, 15, 27):
            eid = int(ctx.split('entity ')[1].split()[0], 16)
            rows.append((f'entity:4,0x{eid:04X}', kind, row['value']))
        elif kind == '29/54':
            m = f"daypart:{row['part']}"
            rows += [(m, 29, row['darkness']), (m, 54, row['light'])]
        else:
            if ctx == 'none':
                m = ''
            else:
                who = 0 if 'party member' in ctx else 4
                m = f"effect:{who},{HELPFUL[kind] if 'helpful' in ctx else HARMFUL[kind]},3,50,3"
            rows.append((m, kind, row['value']))
    return rows


def lines(v):
    out = {}
    singles = []
    for s in v['single']:
        per = ',\n'.join(f"            new({p['index']}, {p['kind']}, {q(entries(p['entries']))})" for p in s['perSlot'])
        singles.append(f"        new({q(s['id'])}, {s['checkpoint']}, {s['slot']}, 0x{s['entity']:04X}, {q(mods(s['mods']))}, {s['radius']}, {ints(s['aiSlots'])}, "
                       f"{b(s['independent'])}, {q(entries(s['full']))}, [\n{per}]),")
    out['SINGLES'] = '\n'.join(singles)

    out['KINDS'] = '\n'.join(f'        new({q(m)}, {kind}, {val}),' for m, kind, val in kind_rows(v['spellValueByKind']))

    can, special = [], []
    for r in v['aiCanCast']:
        if 'special' in r:
            special.append(f"        new({r['special']}, {r['partOfDay']}, {r['requirement']}, {r['timeAllows']}, {b(r['result'])}),")
        elif 'entity' in r:
            ch = -1 if r['charges'] is None else r['charges']
            can.append(f"        new({q(r['label'])}, 0x{r['entity']:04X}, {r['actionSlot']}, {r['kind']}, {r['castLevel']}, {r['cost']}, "
                       f"{r['staminaModified']}, {ch}, {b(r['result'])}),")
    out['AICAN'], out['SPECIALS'] = '\n'.join(can), '\n'.join(special)

    danger = []
    for r in v['danger']:
        c = r['case']
        wiz = sorted((int(m), w) for m, w in c['wizard'].items())
        danger.append(f"        new({ints(int(x, 16) for x in c['flasks'])}, {pairs(c['fireballs'])}, {pairs(wiz)}, {ints(c['dead'])}, "
                      f"{ints(p['wizardModified'] for p in r['party'])}, {r['tier']}, {r['danger']}),")
    out['DANGERS'] = '\n'.join(danger)

    morale, removal = [], []
    for r in v['moraleSpells']:
        if 'kind' in r:
            rounds = ', '.join(f"({x['morale']}, {b(x['recordPresent'])})" for x in r['rounds'])
            morale.append(f"        new({r['kind']}, {r['morale0']}, {r['power']}, {r['timer']}, {r['moraleAfterStart']}, {r['aiFlagsAfterStart']}, "
                          f"{b(r['secondCast'] == 0xFFFF)}, {r['moraleAfterSecond']}, [{rounds}], {r['moraleAtEnd']}),")
        else:
            removal.append(f"        new({q(r['path'])}, {r['moraleAfterStart']}, {b(r.get('ret', 0))}, {r['moraleAfter']}, {b(r['recordPresent'])}),")
    out['MORALES'], out['REMOVALS'] = '\n'.join(morale), '\n'.join(removal)
    return out


def write_cs(v, path):
    """Writes the one-off vectors' table with LF line ends; the bytes written."""
    src = TEMPLATE
    for name, text in lines(v).items():
        src = src.replace(f'@{name}@', text)
    with open(path, 'w', encoding='utf-8', newline='\n') as out:
        out.write(src)
    return len(src.encode('utf-8'))
